public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> permutations = new ArrayList<>();

    // Base case: if the array has only one element, return a list containing only one list with that element
    if (nums.length == 1) {
        permutations.add(new ArrayList<Integer>(Arrays.asList(nums[0])));
        return permutations;
    }

    // Recursive case: for each element in the array, remove it and generate all possible permutations of the remaining elements
    for (int i = 0; i < nums.length; i++) {
        // Clone the array and remove the current element
        int[] remainingNum = Arrays.copyOfRange(nums, 1, nums.length);

        // Generate all possible permutations of the remaining elements
        List<List<Integer>> remainingPermutations = permute(remainingNum);

        // Add the current element to each permutation in the remainingPermutations list
        for (List<Integer> permutation : remainingPermutations) {
            permutation.add(0, nums[i]);
        }

        // Add the current permutation to the overall list of permutations
        permutations.addAll(remainingPermutations);
    }

    return permutations;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums.length == 0) {
        return result;
    } else if (nums.length == 1) {
        result.add(Arrays.asList(nums[0]));
        return result;
    } else {
        for (int i = 0; i < nums.length; i++) {
            int current = nums[i];
            int[] remaining = new int[nums.length - 1];
            System.arraycopy(nums, i + 1, remaining, 0, nums.length - i - 1);
            List<List<Integer>> permutations = permute(remaining);
            for (List<Integer> list : permutations) {
                list.add(current);
            }
            result.addAll(permutations);
        }
    }
    return result;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums == null || nums.length == 0) {
        return result;
    }
    permute(nums, 0, result);
    return result;
}

private void permute(int[] nums, int start, List<List<Integer>> result) {
    if (start == nums.length) {
        result.add(Arrays.stream(nums).boxed().collect(Collectors.toList()));
        return;
    }
    for (int i = start; i < nums.length; i++) {
        swap(nums, start, i);
        permute(nums, start + 1, result);
        swap(nums, start, i);
    }
}

private void swap(int[] nums, int i, int j) {
    int temp = nums[i];
    nums[i] = nums[j];
    nums[j] = temp;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums.length == 0) {
        result.add(new ArrayList<>());
        return result;
    }
    for (int i = 0; i < nums.length; i++) {
        int[] remaining = new int[nums.length - 1];
        System.arraycopy(nums, 0, remaining, 0, i);
        System.arraycopy(nums, i + 1, remaining, i, nums.length - i - 1);
        for (List<Integer> perm : permute(remaining)) {
            perm.add(0, nums[i]);
            result.add(perm);
        }
    }
    return result;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums.length == 0) {
