}

private void permute(int[] nums, int start, List<List<Integer>> result) {
    if (start == nums.length) {
        result.add(new ArrayList<>(Arrays.asList(nums)));
        return;
    }

    for (int i = start; i < nums.length; i++) {
        swap(nums, start, i);
        permute(nums, start + 1, result);
        swap(nums, start, i);
    }
}

private void swap(int[] nums, int i, int j) {
    int temp = nums[i];
    nums[i] = nums[j];
    nums[j] = temp;
}

public int findLargestSubstring(List<String> strings) {
    int largestSubstring = 0;
    for (String string : strings) {
        for (String inverse : strings) {
            if (string.contains(inverse) || inverse.contains(string)) {
                largestSubstring = Math.max(largestSubstring, string.length());
            }
        }
    }
    return largestSubstring;
}

public int findLargestSubstring(List<String> strings) {
    int largestSubstring = 0;
    for (String string : strings) {
        for (int i = 0; i < string.length(); i++) {
            int substringLength = 1;
            int j = i + 1;
            while (j < string.length() && string.charAt(i) == string.charAt(j)) {
                substringLength++;
                j++;
            }
            largestSubstring = Math.max(largestSubstring, substringLength);
        }
    }
    return largestSubstring;
}

