public static int countOilDeposits(char[][] grid) {
    int numDeposits = 0;
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@') {
                numDeposits++;
                // Mark all oils in the same denomination as visited
                visitOils(grid, i, j, '@', '*');
            }
        }
    }
    return numDeposits;
}

private static void visitOils(char[][] grid, int i, int j, char denomination, char replacement) {
    if (i < 0 || j < 0 || i >= grid.length || j >= grid[i].length) {
        return;
    }
    if (grid[i][j] == denomination) {
        grid[i][j] = replacement;
        visitOils(grid, i + 1, j, denomination, replacement);
        visitOils(grid, i - 1, j, denomination, replacement);
        visitOils(grid, i, j + 1, denomination, replacement);
        visitOils(grid, i, j - 1, denomination, replacement);
    }
}

