public static int countOilDeposits(char[][] grid) {
  // Initialize a set to keep track of the oil deposits
  Set<Integer> deposits = new HashSet<>();

  // Loop through each plot and check if there is an oil pocket
  for (int i = 0; i < grid.length; i++) {
    for (int j = 0; j < grid[i].length; j++) {
      char plot = grid[i][j];
      if (plot == '@') {
        // Get the id of the oil deposit
        int id = getOilDepositId(i, j);
        // If the deposit is not already in the set, add it
        if (!deposits.contains(id)) {
          deposits.add(id);
        }
      }
    }
  }

  // Return the number of distinct oil deposits
  return deposits.size();
}

private static int getOilDepositId(int i, int j) {
  // Rotate the plot coordinates to get the id
  int rotatedI = i + j / 2;
  int rotatedJ = j + i % 2;
  return rotatedI * 1000 + rotatedJ;
}

