public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {

    // Create a matrix to represent the n-teresting space
    int[][] matrix = new int[n][n];

    // Set the starting and ending points
    matrix[start[0]][start[1]] = 1;
    matrix[end[0]][end[1]] = 2;

    // Add the paths to the matrix
    for (int[] path : paths) {
        matrix[path[0]][path[1]] = matrix[path[1]][path[0]] = 1;
    }

    // Check if the matrix is connected
    if (isConnected(matrix)) {
        return "can be travelled";
    } else {
        return "cannot be travelled";
    }
}

public static boolean isConnected(int[][] matrix) {

    // Check if the matrix is fully connected
    for (int i = 0; i < matrix.length; i++) {
        for (int j = 0; j < matrix[0].length; j++) {
            if (matrix[i][j] == 0) {
                return false;
            }
        }
    }
    return true;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
  // Initialize a set to keep track of visited n-tersections
  LinkedHashSet<Integer> visited = new LinkedHashSet<>();

  // Add the starting n-tersection to the set
  visited.add(start[0] * n + start[1]);

  // Use a queue to keep track of the n-tersections to visit
  Queue<int[]> queue = new LinkedList<>();
  queue.offer(start);

  while (!queue.isEmpty()) {
    // Get the next n-tersection to visit
    int[] current = queue.poll();

    // Check if the current n-tersection is the ending one
    if (current[0] == end[0] && current[1] == end[1]) {
      return "can be travelled";
    }

    // Add the current n-tersection to the set of visited n-tersections
    visited.add(current[0] * n + current[1]);

    // Get the list of adjacent n-tersections
    List<int[]> neighbors = getNeighbors(n, current, paths);

    // Add the neighbors to the queue
    for (int[] neighbor : neighbors) {
      queue.offer(neighbor);
    }
  }

  // If the queue is empty, it means that the ending n-tersection was not reached, so return "cannot be travelled"
  return "cannot be travelled";
}

private static List<int[]> getNeighbors(int n, int[] point, int[][] paths) {
  int x = point[0];
  int y = point[1];

  // Get the list of paths that connect the current n-tersection to its neighbors
  List<int[]> neighbors = new ArrayList<>();
  for (int[] path : paths) {
    if ((path[0] == x && path[1] == y) || (path[0] == y && path[1] == x)) {
      neighbors.add(new int[] { (x + y) % n, (x + y + 1) % n });
      neighbors.add(new int[] { (x + y + 2) % n, (x + y + 1) % n });
    }
  }

  return neighbors;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[] visited = new boolean[n];
    Deque<Integer> stack = new ArrayDeque<>();
    stack.push(start[0]);
    visited[start[0]] = true;

    while (!stack.isEmpty()) {
        int current = stack.pop();
        if (current == end[0]) { return "can be travelled"; }
        for (int neighbor : paths[current]) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                stack.push(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // check if starting and ending n-tersections are the same
    if (start[0] == end[0] && start[1] == end[1]) {
        return "can be travelled";
    }

    // check if the starting n-tersection is not on any path
    boolean startOnPath = false;
    for (int[] path : paths) {
        if (start[0] == path[0] && start[1] == path[1]) {
            startOnPath = true;
            break;
        }
    }
    if (!startOnPath) {
        return "cannot be travelled";
    }

    // check if the ending n-tersection is not on any path
    boolean endOnPath = false;
    for (int[] path : paths) {
        if (end[0] == path[2] && end[1] == path[3]) {
            endOnPath = true;
            break;
        }
    }
    if (!endOnPath) {
        return "cannot be travelled";
    }

    // check if there are any cycles in the maze
    boolean[] visited = new boolean[paths.length];
    boolean cycleFound = false;
    for (int i = 0; i < paths.length; i++) {
        if (!visited[i]) {
            cycleFound = checkForCycle(i, visited, paths);
            if (cycleFound) {
                break;
            }
        }
    }
    if (cycleFound) {
        return "cannot be travelled";
    }

    // return "can be travelled" if we reach here
    return "can be travelled";
}

private static boolean checkForCycle(int index, boolean[] visited, int[][] paths) {
    visited[index] = true;
    for (int j = 0; j < paths.length; j++) {
        if (!visited[j] && isPathConnected(paths[i], paths[j])) {
            boolean cycleFound = checkForCycle(j, visited, paths);
            if (cycleFound) {
                return true;
            }
        }
    }
    return false;
}

private static boolean isPathConnected(int[] path1, int[] path2) {
    return path1[0] == path2[0] || path1[0] == path2[1] || path1[1] == path2[0] || path1[1] == path2[1];
}

