        dayOfWeek = (dayOfMonth + year + (year / 4)) % 7;
    } else if (year >= 2000) {
        dayOfMonth = month * 30 + day;
        dayOfWeek = (dayOfMonth + year + (year / 4)) % 7;
    }

    switch(dayOfWeek) {
        case 0:
            return "Sunday";
        case 1:
            return "Monday";
        case 2:
            return "Tuesday";
        case 3:
            return "Wednesday";
        case 4:
            return "Thursday";
