    boolean[] seen = new boolean[n];
    int time = 0;
    q.add(0);
    while (!q.isEmpty()) {
        int node = q.poll();
        if (!seen[node]) {
            seen[node] = true;
            time++;
            if (hasApple[node]) {
                return time;
            }
            for (int edge : edges[node]) {
