    visited.add(0);

    while (!queue.isEmpty()) {
        int node = queue.poll();

        if (hasApple[node]) {
            time++;
        }

        for (int neighbor : getNeighbors(edges, node)) {
            if (!visited.contains(neighbor)) {
                queue.add(neighbor);
                visited.add(neighbor);
            }
        }
    }
    return time;
}

private List<Integer> getNeighbors(int[][] edges, int node) {
    List<Integer> neighbors = new ArrayList<>();
    for (int[] edge : edges) {
        if (edge[0] == node) {
            neighbors.add(edge[1]);
        } else if (edge[1] == node) {
            neighbors.add(edge[0]);
        }
    }
    return neighbors;
}

