      rightSum -= arr[i];
      rightLen--;
      leftSum += arr[i];
      leftLen++;
    } else {
      return false;
    }
  }

  return leftSum == rightSum && leftLen == rightLen;
}

public boolean splitArraySameAverage(int[] nums) {
