    for (int i = 0; i < nums.length; i++) {
        total += nums[i];
    }
    double average = total / nums.length;
    double leftSum = 0;
    int leftLength = 0;
    for (int i = 0; i < nums.length; i++) {
        leftSum += nums[i];
        leftLength++;
        if (leftSum == average * leftLength) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int res = 0;
    for (int i = 0; i < cost.length; i++) {
        int curCost = cost[i];
        if (i == 0) {
            res = curCost;
        } else if (i == 1) {
            res = Math.min(curCost, res);
        } else if (i == cost.length - 1) {
            res = Math.min(curCost, res + cost[i - 1]);
        } else {
            res = Math.min(curCost + cost[i - 2], res + cost[i - 1]);
        }
    }
    return res;
}

public int minCostClimbingStairs(int[] cost) {
    int minCost1 = cost[0];
    int minCost2 = cost[1];
    for (int i = 2; i < cost.length; i++) {
        minCost1 += cost[i];
        minCost2 += cost[i - 1];
        if (minCost1 > minCost2) {
            minCost1 = minCost2;
        }
    }
    return Math.min(minCost1, minCost2);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int[] minCost = new int[n];
    if (n == 0) return 0;
    minCost[0] = cost[0];
    minCost[1] = cost[1];
    for (int i = 2; i < n; i++) {
        minCost[i] = Math.min(minCost[i - 1], minCost[i - 2]) + cost[i];
    }
    return Math.min(minCost[n - 1], minCost[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
  int n = cost.length;
  if (n == 0) return 0;
  if (n == 1) return cost[0];
  int[] dp = new int[n];
  dp[0] = cost[0];
  dp[1] = cost[1] + cost[0];
  for (int i = 2; i < n; i++) {
    dp[i] = Math.min(dp[i-1], dp[i-2]) + cost[i];
  }
  return Math.min(dp[n-1], dp[n-2]);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost.length == 0) return 0;
    if (cost.length == 1) return cost[0];
    if (cost.length == 2) return Math.min(cost[0], cost[1]);
    return Math.min(minCostClimbingStairs(cost.subList(0, cost.length - 2)) + cost[cost.length - 1], minCostClimbingStairs(cost.subList(1, cost.length - 1)) + cost[0]);
}

public int minCostClimbingStairs(int[] cost) {
    int dp[] = new int[cost.length + 1];
    dp[0] = 0;
    dp[1] = cost[0];
    for (int i = 2; i <= cost.length; i++) {
        dp[i] = Math.min(dp[i - 1] + cost[i - 1], dp[i - 2] + cost[i - 2]);
    }
    return dp[cost.length];
}

