                // Get the corresponding Morse code for the current letter
                String morseCode = morseCodes[c - 97]; // Assumes that c is lowercase alphabet

                // Add the Morse code to the Morse code representation of the current word
                morseRep += morseCode;
            }

            // If the Morse code representation of the current word is a new one, add it to the map
            if (!morseReps.containsKey(morseRep)) {
                morseReps.put(morseRep, 1);
            } else { // Otherwise, increment the count for the existing Morse code representation
                morseReps.put(morseRep, morseReps.get(morseRep) + 1);
            }
        }

        // Return the number of unique Morse code representations
        return morseReps.size();
    }

