public static int kthFactor(int n, int k) {
    if (n <= 0 || k < 1) return -1;

    Set<Integer> factors = new HashSet<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
            if (i * i < n) factors.add(n / i);
        }
    }

    int[] sortedFactors = factors.stream().mapToInt(f -> f).sorted().toArray();
    if (k > sortedFactors.length) return -1;
    return sortedFactors[k - 1];
}

