    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                for (int[] dir : dirs) {
                    int curr = 1;
                    int x = i + dir[0];
                    int y = j + dir[1];
                    while (x >= 0 && x < m && y >= 0 && y < n && mat[x][y] == 1) {
                        curr++;
