    int[][] directions = {
        {0, 1}, {1, 0}, {1, 1}, {-1, 1}, {1, -1}, {-1, -1}
    };

    int maxLength = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            for (int[] direction : directions) {
                int length = dfs(mat, i, j, direction[0], direction[1], 0);
                maxLength = Math.max(maxLength, length);
            }
        }
    }
    return maxLength;
}

private static int dfs(int[][] mat, int i, int j, int directionI, int directionJ, int length) {
    if (i < 0 || j < 0 || i >= mat.length || j >= mat[0].length || mat[i][j] == 0) {
        return length;
    }
    length++;
    mat[i][j] = 0;
    int newLength = dfs(mat, i + directionI, j + directionJ, directionI, directionJ, length);
    return Math.max(length, newLength);
}

