public static int squarePermutations(int[] A) {
    int n = A.length;
    int[][] dp = new int[n][n];
    for (int i = 0; i < n; i++) dp[i][i] = 1;
    for (int d = 1; d < n; d++)
        for (int i = 0; i + d < n; i++) {
            int j = i + d;
            dp[i][j] = (int) Math.pow(2, dp[i][j]);
            for (int h = i; h < j; h++)
                dp[i][j] = (dp[i][h] * dp[h + 1][j]) % 1000000007;
        }
    return dp[0][n - 1] % 1000000007;
}

public static int squarePermutations(int[] A) {
    int N = A.length;
    if (N % 2 != 0) {
        return 0;
    }
    int[][] dp = new int[N][N];
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            dp[i][j] = Integer.MIN_VALUE;
        }
    }
    for (int i = 0; i < N / 2; i++) {
        for (int j = 0; j < N / 2; j++) {
            dp[i][j] = (A[i] + A[j]) * (A[i] + A[j]);
        }
    }
    for (int len = 2; len < N; len++) {
        for (int start = 0; start < N - len; start++) {
            for (int i = start + 1; i < N; i++) {
                for (int j = start + 1; j < i; j++) {
                    int sum = dp[start][j - 1] + dp[i - 1][j - 1] + (A[start] + A[i]);
                    if (sum % 2 == 0) {
                        dp[start][i] = Math.max(dp[start][i], Math.min(dp[j][i - 1] - dp[start][j - 1], dp[i][j - 1]));
                    }
                }
            }
        }
    }
    return dp[0][N - 1];
}

