    stack.push(n);
    for (int i = n - 1; i >= 0; i--) {
        while (stack.peek() != n && heights[stack.peek()] >= heights[i]) {
            right[i] = stack.pop();
        }
        stack.push(i);
    }

    for (int i = 0; i < n; i++) {
        area[i] = heights[i] * (right[i] - left[i] - 1);
    }

    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        maxArea = Math.max(maxArea, area[i]);
    }

    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
