public static int findSmallestInteger(int n) {
    // tuples of digit count, digit, and the smallest rearranged integer
    List<Tuple<Integer, Integer, Integer>> tuples = new ArrayList<>();

    // calculate the digit count, digit, and the smallest rearranged integer for each digit
    for (int i = 0; i < n; i++) {
        int count = 1;
        int digit = n % 10;
        int rearranged = 0;
        while (n > 0) {
            n /= 10;
            rearranged += n % 10;
            count++;
        }
        tuples.add(new Tuple<>(count, digit, rearranged));
    }

    // find the smallest integer greater than n
    for (Tuple<Integer, Integer, Integer> tuple : tuples) {
        if (tuple.get3() > n) {
            return tuple.get3();
        }
    }

    // if no integer greater than n is found, return -1
    return -1;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) return -1;
    int[] digits = new int[10];
    while (n > 0) {
        digits[n % 10]++;
        n /= 10;
    }
    int smallest = Integer.MAX_VALUE;
    for (int i = 0; i < digits.length; i++) {
        for (int j = 0; j <= digits[i]; j++) {
            int curr = 0;
            for (int k = 0; k < digits.length; k++) {
                curr = curr * 10 + (k == i ? j : digits[k]);
            }
            if (curr > n && curr < smallest) smallest = curr;
        }
    }
    return smallest == Integer.MAX_VALUE ? -1 : smallest;
}

public static int findSmallestInteger(int n) {
    int smallest = -1;
    int[] digits = format(n, reverse = true);
    for (int i = 0; i < digits.length; i++) {
        int num = digits[i];
        for (int j = 0; j < digits.length; j++) {
            if (num == digits[j]) {
                smallest = findNextSmallest(n, digits, i, j);
                if (smallest > n) {
                    break;
                }
            }
        }
        if (smallest > n) {
            break;
        }
    }
    return smallest;
}

private static int findNextSmallest(int n, int[] digits, int i, int j) {
    int[] result = new int[digits.length];
    int k = 0;
    for (int m = 0; m < digits.length; m++) {
        if (m != i && m != j) {
            result[k++] = digits[m];
        }
    }
    int smallest = format(result, reverse = true);
    return smallest;
}

private static int format(int[] digits, bool reverse) {
    int result = 0;
    int factor = 1;
    if (reverse) {
        for (int i = digits.length - 1; i >= 0; i--) {
            result += factor * digits[i];
            factor *= 10;
        }
    } else {
        for (int i = 0; i < digits.length; i++) {
            result += factor * digits[i];
            factor *= 10;
        }
    }
    return result;
}

