    for (int i = 0; i < n; i++) {
        x[i] = points[i][0];
        y[i] = points[i][1];
    }

    // sort x-coordinates
    Arrays.sort(x);

    // check if sorted x-coordinates are equal
    for (int i = 1; i < n; i++) {
