public static int calculateEnergy(String s) {
    int startIndex = 0;
    int endIndex = 0;
    int maxLength = 0;

    for (int i = 0; i < s.length(); i++) {
        if (startIndex < 0) {
            startIndex = i;
        } else if (s.charAt(startIndex) != s.charAt(i)) {
            endIndex = i - 1;
            if (endIndex - startIndex + 1 > maxLength) {
                maxLength = endIndex - startIndex + 1;
            }
            startIndex = i;
        }
    }

    endIndex = s.length() - 1;
    if (endIndex - startIndex + 1 > maxLength) {
        maxLength = endIndex - startIndex + 1;
    }

    return maxLength;
}

public static int calculateEnergy(String s) {
    int len = s.length();
    int[] left = new int[len];
    int[] right = new int[len];
    int maxLen = 0;
    char prevChar = ' ';
    for (int i = 0; i < len; i++) {
        if (s.charAt(i) != prevChar) {
            left[i] = (i == 0) ? 0 : left[i - 1] + 1;
        } else {
            left[i] = left[i - 1];
        }
        prevChar = s.charAt(i);
    }
    prevChar = ' ';
    for (int i = len - 1; i >= 0; i--) {
        if (s.charAt(i) != prevChar) {
            right[i] = (i == len - 1) ? 0 : right[i + 1] + 1;
        } else {
            right[i] = right[i + 1];
        }
        prevChar = s.charAt(i);
    }
    for (int i = 0; i < len; i++) {
        maxLen = Math.max(maxLen, left[i] + right[i]);
    }
    return maxLen;
}

