public static int calculateUniqueSum(int[] nums) {
    // Initialize a set to store unique elements
    Set<Integer> uniqueElements = new HashSet<>();

    // Iterate through the array and add unique elements to the set
    for (int num : nums) {
        uniqueElements.add(num);
    }

    // Initialize a variable to store the sum
    int sum = 0;

    // Iterate through the set and add the elements to the sum
    for (int num : uniqueElements) {
        sum += num;
    }

    // Return the sum
    return sum;
}

