public static int minPerfectSquareSum(int n) {
    if (n < 1) return 0;
    int perfectSquares = 1;
    for (int i = 2; i * i <= n; i++) {
        int squares = 1;
        while (n >= i * i) {
            squares++;
            n -= i * i;
        }
        perfectSquares = Math.min(perfectSquares, squares);
    }
    return perfectSquares;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    int currentSquare = 1;
    while (currentSquare <= n) {
        if (n % currentSquare == 0) {
            count++;
            n /= currentSquare;
        } else {
            currentSquare++;
        }
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
  int sum = 0;
  int count = 0;
  for (int i = 1; i * i <= n; i++) {
    sum += i * i;
    count++;
    if (sum > n) {
      return count - 1;
    }
  }
  return count;
}

